import django.db.models.deletion
from django.db import migrations, models


def asignar_convocatorias_historicas(apps, schema_editor):
    """Enlaza solo cuando el horario deja una única explicación posible.

    Las sesiones solapadas no son evidencia suficiente: esos intentos quedan
    sin vínculo para no atribuirlos dos veces en reportes posteriores.
    """
    SimulationAttempt = apps.get_model("simulation", "SimulationAttempt")
    Convocatoria = apps.get_model("sesiones", "Convocatoria")

    for intento in SimulationAttempt.objects.filter(
        convocatoria__isnull=True, is_rehearsal=False,
    ).iterator():
        candidatas = list(Convocatoria.objects.filter(
            estudiante_id=intento.student_id,
            sesion__case_version_id=intento.case_version_id,
            sesion__inicio__lte=intento.started_at,
            sesion__fin__gt=intento.started_at,
        ).values_list("pk", flat=True)[:2])
        if len(candidatas) == 1:
            SimulationAttempt.objects.filter(pk=intento.pk).update(convocatoria_id=candidatas[0])


